    border: 1px solid var(--border-color);
    padding: 0.8rem 1rem;
    color: white;
    flex: 1;
    border-radius: 4px;
}

.footer-bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 3rem;
