+}
+
+/* Editorial */
+.editorial-section {
+    padding: 8rem 0;
+}
+
+.editorial-grid {
+    display: grid;
+    grid-template-columns: 1.2fr 0.8fr;
+    gap: 6rem;
+    align-items: center;
+}
+
+.editorial-image img {
+    width: 100%;
+    border-radius: 8px;
+}
+
+.editorial-text h2 {
+    font-size: 2.5rem;
+    margin-bottom: 2rem;
+}
+
+.editorial-text p {
+    margin-bottom: 1.5rem;
+    font-size: 1.1rem;
+    color: var(--text-muted);
+}
+
